begin;
do $test$
declare root uuid;root_session uuid:=gen_random_uuid();other_owner uuid:=gen_random_uuid();other_session uuid:=gen_random_uuid();target_user uuid:=gen_random_uuid();target_session uuid:=gen_random_uuid();rev bigint;denied boolean;
begin
 select owner_id into root from study_private.settings where singleton;
 select revision into rev from study_private.admin_password_settings where singleton and password_hash is not null;
 insert into auth.users(id,email,email_confirmed_at)values(other_owner,'counsel-role-test-'||other_owner||'@example.invalid',now()),(target_user,'counsel-role-test-'||target_user||'@example.invalid',now());
 insert into study_private.admin_members(user_id)values(other_owner),(target_user);
 insert into study_private.owner_members(user_id,added_by)values(other_owner,root),(target_user,root);
 insert into auth.sessions(id,user_id,not_after)values(root_session,root,now()+interval '1 hour'),(other_session,other_owner,now()+interval '1 hour'),(target_session,target_user,now()+interval '1 hour');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',root,'session_id',root_session,'role','authenticated')::text,true);perform set_config('request.jwt.claim.sub',root::text,true);
 set local role authenticated;
 denied:=false;begin perform public.study_counsel_revoke(target_user,target_user::text);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Password receipt bypass';end if;
 reset role;
 insert into study_private.admin_verified_sessions(actor,session_id,password_revision,expires_at)values(root,root_session,rev,now()+interval '5 minutes'),(other_owner,other_session,rev,now()+interval '5 minutes'),(target_user,target_session,rev,now()+interval '5 minutes');
 insert into study_private.counsel_pledges(actor,session_id,version)values(target_user,target_session,1);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other_owner,'session_id',other_session,'role','authenticated')::text,true);perform set_config('request.jwt.claim.sub',other_owner::text,true);
 set local role authenticated;
 denied:=false;begin perform public.study_counsel_revoke(target_user,target_user::text);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Ordinary owner revoked roles';end if;
 reset role;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',root,'session_id',root_session,'role','authenticated')::text,true);perform set_config('request.jwt.claim.sub',root::text,true);
 set local role authenticated;
 denied:=false;begin perform public.study_counsel_revoke(root,root::text);exception when invalid_parameter_value then denied:=true;end;if not denied then raise exception 'Supreme owner removal';end if;
 denied:=false;begin perform public.study_counsel_revoke(target_user,'wrong');exception when invalid_parameter_value then denied:=true;end;if not denied then raise exception 'Missing target confirmation';end if;
 perform public.study_counsel_revoke(target_user,target_user::text);
 reset role;
 if exists(select 1 from study_private.admin_members where user_id=target_user)or exists(select 1 from study_private.owner_members where user_id=target_user)or exists(select 1 from study_private.admin_verified_sessions where actor=target_user)or exists(select 1 from study_private.counsel_pledges where actor=target_user)then raise exception 'Revoked role or receipt retained';end if;
 if not exists(select 1 from auth.users where id=target_user)then raise exception 'Account removed';end if;
 if not exists(select 1 from study_private.audit_events where actor=root and target=target_user and action='counsel_roles_revoked'and protected)then raise exception 'Protected audit missing';end if;
 if has_function_privilege('anon','public.study_counsel_revoke(uuid,text)','execute')then raise exception 'Anon revoke';end if;
end $test$;
select 'PASS: only verified supreme owner can revoke; ordinary owner, missing receipt, wrong confirmation and supreme self-removal rejected; target account retained, role and receipts removed, protected audit recorded. All test changes rolled back.' result;
rollback;
